add_filter( 'woocommerce_get_breadcrumb', 'perfectpixel_rename_breadcrumb_items' );

function perfectpixel_rename_breadcrumb_items( $crumbs ) {
	$map = array();
	foreach ( explode( '|', '{{breadcrumb_renames}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && '' !== $parts[0] ) {
			$map[ $parts[0] ] = $parts[1];
		}
	}
	foreach ( $crumbs as $i => $crumb ) {
		$text = trim( wp_strip_all_tags( $crumb[0] ) );
		if ( isset( $map[ $text ] ) ) {
			$crumbs[ $i ][0] = $map[ $text ];
		}
	}
	return $crumbs;
}
